actions.script:
const given = name => (typeof ec.context[name] === 'undefined' || ec.context[name] === '' ? null : ec.context[name])
const direction = given('directionEnumId')
let punched = null
let refusal = null
ec.message.pushErrors()
try {
    punched = ec.service.sync().name('mantle.humanres.AttendanceServices.record#KioskPunch').parameters({
        badgeText: given('badgeText') || given('badgeText_scanText'), pin: given('password'),
        directionEnumId: ['AtdIn', 'AtdOut'].includes(direction) ? direction : null, operationKey: given('operationKey')
    }).requireNewTransaction(true).call()
    if (ec.message.hasError()) refusal = ec.message.getErrorsString()
} catch (error) {
    refusal = String(error.message || error)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (refusal) {
    // a refusal names its reason (CODE: message); anything else is a failure the worker cannot fix here
    const coded = /\b([A-Z][A-Z0-9_]{3,}):\s*([^\n]*)/.exec(refusal)
    if (!coded) ec.logger.warn('Clocking kiosk punch failed: ' + refusal)
    ec.message.addMessage(coded ? ec.l10n.localize(coded[2]) : ec.l10n.localize('Not recorded. Try again.'), 'danger')
} else {
    ec.message.addMessage(punched.personName + ': ' + ec.l10n.localize(punched.directionEnumId == 'AtdIn' ? 'clocked in at' : 'clocked out at') +
        ' ' + punched.punchTimeText, 'success')
}

onDevice = !!UserSecurityChecks.currentDevice()
// the employer the device serves: its display account's organization (the People root's setup#UserOrganizationInfo)
employerName = Array.from(ec.context.userOrgList || []).map(org => org.organizationName).filter(Boolean).join(', ')
if (sri.getRenderMode() == 'html') {
    // the html page: the theme's style sheets, the qvt client's files and this screen as an island (WebrootPublic.qvt.js)
    const qvtLib = ec.resource.script('component://webroot/screen/includes/QvtConfig.js')
    const localeTag = String(ec.user.locale || 'en_US').replace('_', '-')
    const quasarLang = qvtLib.quasarLangOf(localeTag)
    const sheets = Array.from(sri.getThemeValues('STRT_STYLESHEET'))
    const scripts = ['/libs/vue/vue.global.prod.js', '/libs/quasar/quasar.umd.prod.js', '/libs/quasar/lang/' + quasarLang + '.umd.prod.js']
    if (sheets.some(sheet => String(sheet).includes('/libs/material-symbols/'))) scripts.push('/libs/quasar/icon-set/material-symbols-outlined.umd.prod.js')
    scripts.push('/js/MoquiLib.js', '/js/MoquiL10n.js', '/js/WebrootVue.qvt.render.js', '/js/WebrootVue.qvt.js', '/js/WebrootPublic.qvt.js')
    const version = '?v=' + ec.web.getResourceDistinctValue()
    const href = location => WebUtilities.encodeHtml(sri.buildUrl(location).url + version)
    kioskHead = sheets.map(sheet => '<link rel="stylesheet" href="' + href(sheet) + '">').join('')
    kioskScripts = scripts.map(script => '<script src="' + href(script) + '"></script>').join('')
    kioskLang = WebUtilities.encodeHtml(localeTag)
    kioskTitle = WebUtilities.encodeHtml(ec.l10n.localize('Clock in or out'))
    const island = {
        shell: 'island', sessionToken: ec.web.sessionToken, appRootPath: '', locale: localeTag, timeZone: ec.user.timeZone,
        quasarLang: quasarLang.replace(/-([a-zA-Z])/g, (m, ch) => ch.toUpperCase()),
        quasar: {notify: {progress: true, position: 'top', timeout: 6000}},
        qvt: {build: 'compiler', handles: ['merged-fragment', 'static-template']},
        route: {name: 'clocking-kiosk', basePath: sri.buildUrl('.').path, title: ec.l10n.localize('Clock in or out'), renderModes: ['qvt']},
        context: {}, labels: {loading: ec.l10n.localize('Loading'), notFound: ec.l10n.localize('This clock is not available.')}
    }
    kioskIsland = JSON.stringify(island).split('<').join('\\u003c')
}
